code_sketch:
#include <assert.h>

typedef struct { int used; int capacity; } buffer;

static void buffer_put(buffer *b, int v) {
    assert(b->used < b->capacity);   /* precondition: room for one more */
    /* ... */
    b->used++;
    assert(b->used <= b->capacity);  /* postcondition / invariant */
}

